namespace Gordic.Ada.WebClient {
    var gcontent = Decorators.gcontent;

    @gcontent
    export class GSeznamDokumentyADA extends GContentBase {

        private row: Gordic.Ssl.Interface.GDokumentDto;

        private view_ISL: Gordic.Isl.View<Gordic.Ssl.Interface.GDokumentDto>;
        private filter: Gordic.Ssl.Interface.GDokumentFilterDto;
        private gridFormatSeznam: Gordic.Data.GridFormat<Gordic.Ssl.Interface.GDokumentDto>;

        private readonly globals: Gordic.Ada.WebClient.DTO.GAdaGlobalsDto;

        private mainTable: JQuery;
                
        previewController: Gordic.Previews.GPreviewController;
        previewDiv: JQuery<HTMLElement>;
        rowToPreview: any;

        title = "Dokumenty ADA";
        taskId = "actDokumentyADA"; // označení položky v taskListu

        onContentReady() {

            var that = this;
            var $tab = $(this.contentDiv);

            $tab.empty();

            var cnt = this;

            var mainForm = $("<div>").appendTo(this.element).gform("setup", { layoutDescriptor: "L1M1S1 LMS-0-12-0" }).gformsection("create");

            this.actions.addRange({
                actGridDoubleClick: {
                    caption: "Detail",
                    run: function (ev, ctx) {

                        var vybraneRadky;

                        vybraneRadky = cnt.find(".js-SeznamDocumentyAda").ggrid("activeRow", false);
                        if (vybraneRadky.ixp) {
                            var modOtevreni = Gordic.Global.Enums.ModOtevreni.showModalWindow;

                            var params = {
                                DetailDto: { ixp: vybraneRadky.ixp },
                            };

                            Gordic.Ssl.Dialogs.Detail(cnt, params, modOtevreni);
                        }

                        return true;
                    }
                }
            });
            //nastavení menuBaru
            this.menuBar(this.actions.createBar(["actGridDoubleClick*"]));

            cnt.gridFormatSeznam = new Gordic.Data.GridFormat<Gordic.Ssl.Interface.GDokumentDto>();

            cnt.gridFormatSeznam.addIconColumn(Gordic.Wfl.Globals.ListSupport.PoziceSpisColumnDlg())

            cnt.gridFormatSeznam 
            .addTextColumn({               //sloupce pridane pred cfu
                name: "ixp",
                caption: "PID",
                customClass: "dt-left",
                width: 140
            })
            .addTextColumn({               //sloupce pridane pred cfu
                name: "nazev",
                caption: "Věc",
                customClass: "dt-left",
                width: 300
            })
            .addTextColumn({               //sloupce pridane pred cfu
                name: "obsah_text",
                caption: "Věc podrobně",
                customClass: "dt-left",
                width: 300
            })
            .addDateColumn({
                name: "dat_pod",
                caption: "Datum podání",
                customClass: "dt-left",
                width: 140
            })
            //.addTextColumn({               //sloupce pridane pred cfu
            //    name: "ixp_spis",
            //    caption: "Vloženo ve spisu",
            //    customClass: "dt-left",
            //    width: 140
            //})
            .addTextColumn({               //sloupce pridane pred cfu
                name: "ixp_spis_prir",
                caption: "Přiřazeno ke spisu",
                customClass: "dt-left",
                width: 140
            })
            .addNumberColumn({               //sloupce pridane pred cfu
                name: "poc_priloh",
                caption: "Počet příloh",
                customClass: "dt-left",
                width: 40
            })
            .addTextColumn({               //sloupce pridane pred cfu
                name: "VlastnikFunkce.nazev_rf",
                caption: "Vlastník",
                customClass: "dt-left",
                width: 300
            })
            ;


            cnt.mainTable = $("<div class='js-SeznamDocumentyAda'>")
                //.css("height", "100%")
                .appendTo(mainForm)
                .gautofit()
                .ggrid({
                    columnMode: "full",
                    multi: true,
                    defaultAction: cnt.actions.actGridDoubleClick,
                    selection: function (ev, selectionInfo) {
                        // var data = that.view_ISL.getDataRows();
                        console.log( selectionInfo );
                    },
                    searchColumns: Gordic.Ada.WebClient.AdaFunction.zjisti_sloupce_search(cnt.gridFormatSeznam),
                    columns: cnt.gridFormatSeznam,

                    defaultProfile: {
                        columnList: cnt.zjisti_sloupce(cnt.gridFormatSeznam)
                    },
                    profiles: [
                        { name: "Úplný", columnList: this.zjisti_sloupce(cnt.gridFormatSeznam), _locked: true } //gridFormatSeznam.columns.filter((c) => c.name != "kniha").join() },
                    ],
                });

            cnt.filter = {};
            cnt.filter.typ_ag = [250];
            cnt.filter.s_stor = 0;
             
            that.view_ISL = new Gordic.Isl.View(this.isl.Dokument.list({ filters: cnt.filter, fragments: ["Permissions", "*", "VlastnikFunkce.*"] }));

            cnt.mainTable.ggrid("setData", that.view_ISL);

        }

        zjisti_sloupce(gf) {
            return gf.columns.filter(e => e.hidden != true).map(e => e.name).join(',');
        }
    }
}
